INSERT INTO articles (slug,title,teaser,body,category,topic,region,kind,author,image,source_name,source_url,status,published_at,updated_at,meta_title,meta_description,focus_keyword,keywords,image_alt,image_prompt,faq,service) VALUES ('geldwaesche-oesterreich-bundesrat-neue-regeln-register-2027','Geldwäsche in Österreich: Bundesrat billigt neue EU-Regeln','Der Bundesrat hat neue Regeln gegen Geldwäsche, das Registergesetz 2027 und mehrere Steuerabkommen gebilligt. Die Grünen stimmten gegen das Geldwäsche-Paket.','Im Kampf gegen **Geldwäsche in Österreich** hat der Bundesrat am Donnerstag ein umfangreiches Gesetzespaket gebilligt. Die Länderkammer stimmte in ihrer Sitzung vom 22. Oktober 2026 mehrheitlich für Änderungen, mit denen EU-Vorgaben umgesetzt und die Unabhängigkeit der Finanzmarktaufsicht (FMA) gestärkt werden sollen. Das berichtet die Parlamentskorrespondenz. Zugleich gab es grünes Licht für ein neues Registergesetz zu wirtschaftlichen Eigentümern.

## Geldwäsche in Österreich: Was das neue Paket regelt

Kern des Pakets ist die Umsetzung der 6. EU-Geldwäscherichtlinie sowie der EU-Geldwäscheverordnung in österreichisches Recht. Ziel ist es, Geldflüsse transparenter zu machen und den Behörden bessere Kontrollmöglichkeiten in die Hand zu geben. Die europäischen Regeln sollen verhindern, dass illegal erworbenes Vermögen über Scheinfirmen oder verschachtelte Firmenkonstruktionen in den legalen Wirtschaftskreislauf gelangt.

Ebenfalls mehrheitlich befürwortet wurde das **Wirtschaftliche Eigentümer Registergesetz 2027**. Es soll die Regeln zum wirtschaftlichen Eigentum EU-weit vereinheitlichen und den rechtlichen Rahmen für die entsprechenden Register verbessern. Gemeint ist damit, offenzulegen, welche natürlichen Personen tatsächlich hinter einem Unternehmen stehen und davon profitieren.

Für die Bundesregierung verwies Staatssekretärin Barbara Eibinger-Miedl in der Debatte darauf, dass Geldwäsche und Scheinunternehmen nur mit internationaler Zusammenarbeit und gemeinsamen europäischen Regeln wirksam bekämpft werden könnten.

## So positionierten sich die Fraktionen

Die Debatte im Bundesrat zeigte unterschiedliche Bewertungen:

- **ÖVP:** Bundesrat Christoph Thoma (Vorarlberg) sah in den Änderungen einen Beitrag zu fairem Wettbewerb, weniger Bürokratie und rascheren Verfahren.
- **SPÖ:** Martin Peterl (Niederösterreich) bezeichnete das Paket als wichtiges Werkzeug, mahnte aber eine praxistaugliche Umsetzung ohne Doppelmeldungen ein.
- **FPÖ:** Irene Partl (Tirol) stimmte zu, äußerte sich aber skeptisch zu zusätzlichen Kontrollen durch die Finanzpolizei. Diese solle dort prüfen, wo tatsächlich Betrug stattfinde.
- **Grüne:** Elisabeth Kittl (Wien) lehnte ab. Aus ihrer Sicht schöpft die Umsetzung nicht alle Möglichkeiten aus, etwa im Vorgehen gegen Strohmänner und Wirtschaftskriminelle.

## Steuerabkommen und Schadensdatenbank beschlossen

Neben dem Geldwäsche-Paket passierten weitere Vorlagen die Länderkammer. Einstimmig angenommen wurden modernisierte Doppelbesteuerungsabkommen mit der Schweiz und Katar sowie ein neues Abkommen mit Andorra. Ebenfalls einhellig billigte der Bundesrat die Anpassung einer österreichischen Erklärung aus dem Jahr 2014 zum internationalen Übereinkommen über gegenseitige Amtshilfe in Steuersachen.

Mehrheitlich beschlossen wurde außerdem eine Novelle zum GeoSphere-Austria-Gesetz. Sie schafft die Grundlage für eine Datenbank, in der Schäden durch Naturereignisse erfasst werden. Diese soll sich an den Kriterien des Büros der Vereinten Nationen für Katastrophenvorsorge (UNDRR) orientieren. Wissenschaftsministerin Eva-Maria Holzleitner argumentierte, dass zunehmende Wetterextreme die Arbeit der GeoSphere wichtiger machten und bessere Vorsorge Schäden und Kosten senken könne. Kritik kam von der FPÖ, die Unklarheiten und mögliche Doppelerfassungen befürchtet; die Grünen forderten eine verbindliche Zusammenarbeit von Bund und Ländern.

## Enquete zu starken Regionen am 23. November

Einstimmig beschloss der Bundesrat zudem eine parlamentarische Enquete unter dem Titel „Wohlstand, Wandel, Weitblick: Starke Regionen für Österreichs Zukunft“. Sie findet am Montag, 23. November, im Parlament statt. Eröffnet wird sie von Bundesratspräsidentin Christine Schwarz-Fuchs, die Keynote hält Vorarlbergs Landeshauptmann Markus Wallner. Geplant sind Panels zu Wirtschaft, Bildung und Resilienz der Regionen sowie Stellungnahmen der Parteien.

## Was die Beschlüsse bedeuten

Mit der Zustimmung des Bundesrats ist die parlamentarische Behandlung der Vorlagen abgeschlossen. Für Unternehmen, Banken und andere meldepflichtige Branchen bedeutet die Umsetzung der EU-Vorgaben, dass Transparenz- und Sorgfaltspflichten im Kampf gegen Geldwäsche weiter an Bedeutung gewinnen. Wann die einzelnen Bestimmungen in Kraft treten, geht aus der Mitteilung der Parlamentskorrespondenz nicht hervor.','politik','Parlament',NULL,'news','Presseinfo Redaktion','/assets/img/artikel/geldwaesche-oesterreich-bundesrat-neue-regeln-register-2027.webp','Parlamentskorrespondenz (OTS)','https://www.ots.at/presseaussendung/OTS_20261022_OTS0218/bundesrat-befuerwortet-neue-regeln-zur-bekaempfung-von-geldwaesche','published','2026-10-23T04:55:00.000Z','2026-10-23T04:44:25.565Z','Geldwäsche Österreich: Bundesrat billigt neue Regeln','Geldwäsche in Österreich: Der Bundesrat hat neue EU-Regeln, ein Register für wirtschaftliche Eigentümer und Steuerabkommen gebilligt. Alle Details.','Geldwäsche Österreich','["Geldwäsche Österreich","Bundesrat","Geldwäscherichtlinie","EU-Geldwäscheverordnung","Wirtschaftliche Eigentümer Registergesetz 2027","Finanzmarktaufsicht FMA","Bundesrat Sitzung Oktober 2026","Doppelbesteuerungsabkommen Schweiz Katar","Schadensdatenbank GeoSphere Austria"]','Geldwäsche Österreich: Euro-Banknoten und Dokumente mit Lupe auf einem Schreibtisch','Stack of euro banknotes and financial documents with a magnifying glass on a dark wooden desk in a historic Viennese government office, soft morning light, no text, no logos, no readable signs','[{"q":"Was hat der Bundesrat zur Geldwäsche beschlossen?","a":"Er billigte mehrheitlich die Umsetzung der 6. EU-Geldwäscherichtlinie und der EU-Geldwäscheverordnung sowie eine Stärkung der Unabhängigkeit der FMA."},{"q":"Was ist das Wirtschaftliche Eigentümer Registergesetz 2027?","a":"Es soll die Regeln zum wirtschaftlichen Eigentum EU-weit harmonisieren und den Rechtsrahmen für die Register verbessern, die die tatsächlichen Eigentümer von Firmen offenlegen."},{"q":"Wer stimmte gegen das Geldwäsche-Paket?","a":"Die Grünen lehnten ab, weil die Umsetzung aus ihrer Sicht nicht alle Möglichkeiten gegen Strohmänner und Wirtschaftskriminelle nutzt."}]',0) ON CONFLICT(slug) DO UPDATE SET title=excluded.title, teaser=excluded.teaser, body=excluded.body, category=excluded.category, topic=excluded.topic, region=excluded.region, kind=excluded.kind, author=excluded.author, source_name=excluded.source_name, source_url=excluded.source_url, status=excluded.status, published_at=excluded.published_at, updated_at=excluded.updated_at, meta_title=excluded.meta_title, meta_description=excluded.meta_description, focus_keyword=excluded.focus_keyword, keywords=excluded.keywords, image_alt=excluded.image_alt, image_prompt=excluded.image_prompt, faq=excluded.faq, service=excluded.service, image=COALESCE(excluded.image, articles.image);
